const preferences: Record<string, boolean> = {
  "user-1": true,
};

export function getNotificationPreference(userId: string): boolean {
  return preferences[userId] ?? false;
}

export function toggleNotificationPreference(userId: string): boolean {
  const current = getNotificationPreference(userId);
  preferences[userId] = !current;
  return preferences[userId];
}

