import { getNotificationPreference } from "./data";
import { toggleNotifications } from "./actions";

export default function Home() {
  const enabled = getNotificationPreference("user-1");

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? "ON" : "OFF"}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? "off" : "on"}
        </button>
      </form>
    </main>
  );
}

